#!/usr/bin/env python3
"""TanStack Router's route tree generated by ours (src/tanstack, out/bin/tsrgen) and by theirs
(@tanstack/router-generator, run by tools/router-gen-theirs.mjs), compared byte for byte: the tree and
every route file each leaves behind (both fix route ids and imports in route files).

Random projects: routes nested in directories and flat (`a.b.tsx`), params, splats, optional params,
pathless layouts, route groups, index and route tokens, `.lazy` routes and component and loader
pieces, ignored files, escaped segments, files that are not routes, route ids and imports to fix,
long names that cross Prettier's 80 columns; and configurations: quotes, semicolons, types off,
extensions, headers and footers, formatting off, other directories and tokens, absolute imports,
the solid and vue targets. A project both reject (a conflict) must be rejected by both.

Also the benchmarks/tanstack-router application, whose tree must come out as committed.

usage: router-gen-check.py [COUNT] [SEED] [TSRGEN]
"""
import json
import os
import random
import shutil
import subprocess
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
COUNT = int(sys.argv[1]) if len(sys.argv) > 1 else 300
SEED = int(sys.argv[2]) if len(sys.argv) > 2 else 1
TSRGEN = os.path.abspath(sys.argv[3]) if len(sys.argv) > 3 else os.path.join(ROOT, "out/bin/tsrgen")
OUT = os.path.join(ROOT, "out/router-gen-check")
THEIRS = os.path.join(ROOT, "tools/router-gen-theirs.mjs")
APP = os.path.join(ROOT, "benchmarks/tanstack-router")

WORDS = ["about", "posts", "users", "settings", "a", "b", "dashboard", "profile", "team", "billing", "invoices",
         "x", "docs", "blog", "faq", "help", "api", "admin", "reports"]


def word(rng):
    w = rng.choice(WORDS)
    r = rng.random()
    if r < 0.08:
        return w + "-" + rng.choice(WORDS)
    if r < 0.12:
        return w + str(rng.randint(1, 9))
    if r < 0.16:
        return "averyveryverylongsegmentname" + rng.choice(WORDS) * rng.randint(1, 3)
    return w


def segment(rng, tokens, last=False):
    """One path segment of a route file's name."""
    r = rng.random()
    if r < 0.12:
        return "$" + rng.choice(["id", "postId", "userId", "slug"])
    if r < 0.15:
        return "{-$" + rng.choice(["lang", "page"]) + "}"
    if r < 0.24:
        return "_" + rng.choice(["layout", "auth", "app", "shell"])
    if r < 0.30 and not last:
        return "(" + rng.choice(["marketing", "app", "group"]) + ")"
    if r < 0.33:
        return rng.choice(["[.]well-known", "[_]escaped", "trail[_]", "[index]", "[route]", "file[.]json"])
    return word(rng)


def route_body(rng, quote, ctor="createFileRoute", route_id=None):
    rid = route_id if route_id is not None else rng.choice(["/wrong", "/"])
    q = quote
    imp = rng.random()
    if imp < 0.7:
        head = "import { %s } from '@tanstack/react-router'\n" % ctor
    elif imp < 0.8:
        head = "import { Link, %s } from \"@tanstack/react-router\";\n" % ctor
    elif imp < 0.88:
        head = ""
    elif imp < 0.94:
        other = "createLazyFileRoute" if ctor == "createFileRoute" else "createFileRoute"
        head = "import { %s } from '@tanstack/react-router'\n" % other
    else:
        head = "import * as R from '@tanstack/react-router'\nimport { %s, Outlet } from '@tanstack/react-router'\n" % ctor
    if rng.random() < 0.1:
        return head + "const R0 = %s(%s%s%s)({ component: () => null })\nexport { R0 as Route }\n" % (ctor, q, rid, q)
    return head + "\nexport const Route = %s(%s%s%s)({\n  component: () => null,\n})\n" % (ctor, q, rid, q)


def make_project(rng, d):
    """A random project in `d`; its configuration's options as a dict."""
    config = {}
    tokens = {"index": "index", "route": "route"}
    if rng.random() < 0.08:
        config["indexToken"] = "idx"
        tokens["index"] = "idx"
    if rng.random() < 0.08:
        config["routeToken"] = "layout"
        tokens["route"] = "layout"
    routes_dir = "src/routes"
    if rng.random() < 0.1:
        routes_dir = "app/pages"
        config["routesDirectory"] = "./app/pages"
    if rng.random() < 0.1:
        config["generatedRouteTree"] = rng.choice(["./src/gen/routeTree.gen.ts", "./routeTree.gen.ts", "./src/routes/routeTree.gen.tsx"])
    if rng.random() < 0.15:
        config["quoteStyle"] = "double"
    if rng.random() < 0.15:
        config["semicolons"] = True
    if rng.random() < 0.1:
        config["disableTypes"] = True
    if rng.random() < 0.1:
        config["addExtensions"] = rng.choice([True, ".js", "jsx"])
    if rng.random() < 0.1:
        config["enableRouteTreeFormatting"] = False
    if rng.random() < 0.1:
        config["routeTreeFileHeader"] = rng.choice([[], ["// a header"], ["/* one */", "// two"], ["/**\n * documented\n */"]])
    if rng.random() < 0.1:
        config["routeTreeFileFooter"] = rng.choice([["// the end"], ["// one", "// two"], ["/* block */"]])
    if rng.random() < 0.05:
        config["importRoutesUsingAbsolutePaths"] = True
    if rng.random() < 0.06:
        config["routeFileIgnorePrefix"] = "~"
    if rng.random() < 0.05:
        config["target"] = rng.choice(["solid", "vue"])
    prefix = config.get("routeFileIgnorePrefix", "-")
    base = os.path.join(d, routes_dir)
    os.makedirs(base)
    quote = "'" if rng.random() < 0.7 else rng.choice(['"', "`"])
    pkg = "@tanstack/%s-router" % config.get("target", "react")
    files = {}
    files["__root.tsx"] = "import { createRootRoute } from '%s'\nexport const Route = createRootRoute()\n" % pkg
    for _ in range(rng.randint(1, 14)):
        depth = rng.choice([1, 1, 2, 2, 3])
        segs = [segment(rng, tokens, i == depth - 1) for i in range(depth)]
        # Mostly paths of their own, so that most projects have no conflicts.
        if rng.random() < 0.7:
            segs[-1] = segs[-1] + "u%d" % len(files) if not segs[-1].startswith("(") else segs[-1]
        last = rng.random()
        if last < 0.15:
            segs.append(tokens["index"])
        elif last < 0.25:
            segs.append(tokens["route"])
        piece = ""
        p = rng.random()
        if p < 0.1:
            piece = ".lazy"
        elif p < 0.14:
            piece = rng.choice([".component", ".loader", ".errorComponent", ".pendingComponent"])
        ext = rng.choice([".tsx", ".tsx", ".tsx", ".ts", ".jsx", ".js"])
        flat = rng.random() < 0.4
        if flat:
            rel = ".".join(segs) + piece + ext
        else:
            rel = "/".join(segs[:-1] + [segs[-1] + piece + ext])
        if rel.startswith(".") or "/." in rel:
            continue
        lazy = piece == ".lazy"
        ctor = "createLazyFileRoute" if lazy else "createFileRoute"
        if piece in (".component", ".loader", ".errorComponent", ".pendingComponent"):
            body = "export const %s = () => null\n" % piece[1:]
        else:
            body = route_body(rng, quote, ctor if rng.random() < 0.9 else ("createFileRoute" if lazy else "createLazyFileRoute"))
            body = body.replace("@tanstack/react-router", pkg)
        files[rel] = body
    for _ in range(rng.randint(0, 2)):
        files[prefix + word(rng) + ".tsx"] = "export const helper = 1\n"
    if rng.random() < 0.2:
        files[word(rng) + "-utils.ts"] = "export const notARoute = 1\n"
    for rel, body in files.items():
        path = os.path.join(base, rel)
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w") as f:
            f.write(body)
    if config:
        with open(os.path.join(d, "tsr.config.json"), "w") as f:
            json.dump(config, f, indent=2)
    return config


def snapshot(d):
    out = {}
    for dirpath, dirnames, filenames in os.walk(d):
        dirnames[:] = [x for x in dirnames if x != ".tanstack"]
        for name in filenames:
            p = os.path.join(dirpath, name)
            # Absolute imports name the project's own directory, which differs between the copies.
            out[os.path.relpath(p, d)] = open(p, "rb").read().replace(d.encode(), b"<project>")
    return out


def run_ours(d):
    p = subprocess.run([TSRGEN, "generate", d], capture_output=True, text=True)
    return ("ok" if p.returncode == 0 else "error " + (p.stdout + p.stderr).strip().split("\n")[0])


def main():
    shutil.rmtree(OUT, ignore_errors=True)
    os.makedirs(OUT)
    rng = random.Random(SEED)
    cases = []
    for i in range(COUNT):
        d = os.path.join(OUT, "case%d" % i)
        os.makedirs(d)
        config = make_project(rng, d)
        theirs, ours = d + "-theirs", d + "-ours"
        shutil.copytree(d, theirs)
        shutil.copytree(d, ours)
        cases.append((d, theirs, ours, config))
    # The application, from its sources, its tree left out.
    app = os.path.join(OUT, "app")
    shutil.copytree(os.path.join(APP, "src"), os.path.join(app, "src"))
    os.remove(os.path.join(app, "src/routeTree.gen.ts"))
    shutil.copytree(app, app + "-theirs")
    shutil.copytree(app, app + "-ours")
    cases.append((app, app + "-theirs", app + "-ours", {}))

    p = subprocess.run(["node", THEIRS] + [c[1] for c in cases], capture_output=True, text=True)
    statuses = p.stdout.strip().split("\n")
    if len(statuses) != len(cases):
        print(p.stdout, p.stderr)
        sys.exit("router-gen-check: their generator stopped early")

    failed = []
    agree_errors = 0
    for (d, theirs, ours, config), status in zip(cases, statuses):
        mine = run_ours(ours)
        if status.startswith("error") or mine.startswith("error"):
            if status.startswith("error") and mine.startswith("error") and status[len("error "):] == mine[len("error error: "):]:
                agree_errors += 1
                if os.environ.get("SHOW_ERRORS"):
                    print("both reject", os.path.basename(d), "|", status[:150], "|", mine[:150])
                continue
            failed.append((d, "theirs: %s / ours: %s" % (status, mine)))
            continue
        a, b = snapshot(theirs), snapshot(ours)
        if a != b:
            differing = sorted(k for k in set(a) | set(b) if a.get(k) != b.get(k))
            failed.append((d, "files differ: " + ", ".join(differing[:5])))
    app_tree = open(os.path.join(app + "-ours", "src/routeTree.gen.ts")).read() if os.path.exists(os.path.join(app + "-ours", "src/routeTree.gen.ts")) else ""
    app_same = app_tree == open(os.path.join(APP, "src/routeTree.gen.ts")).read()

    for d, why in failed[:20]:
        print("FAIL", os.path.basename(d), why)
    print("ok  " if app_same else "FAIL", "the application's tree comes out as committed")
    print("router-gen-check: %d projects, %d identical, %d rejected by both, %d differ"
          % (len(cases), len(cases) - len(failed) - agree_errors, agree_errors, len(failed)))
    sys.exit(1 if failed or not app_same else 0)


if __name__ == "__main__":
    main()
